1	import { syntaxTree } from '@codemirror/language';
2	import { Range } from '@codemirror/state';
3	import {
4	  Decoration,
5	  DecorationSet,
6	  EditorView,
7	  ViewPlugin,
8	  ViewUpdate,
9	} from '@codemirror/view';
10	import { shouldShowSource } from '../core/shouldShowSource';
11	import { mouseSelectingField } from '../core/mouseSelecting';
12	import { checkUpdateAction } from '../core/pluginUpdateHelper';
13	
14	/**
15	 * Parent node types to skip
16	 * Marks inside these nodes should not be processed
17	 */
18	const SKIP_PARENT_TYPES = new Set(['FencedCode', 'CodeBlock']);
19	
20	/**
21	 * Check if node is inside a skipped parent
22	 */
23	function isInsideSkippedParent(node: {
24	  node: { parent: { name: string; parent: unknown } | null };
25	}): boolean {
26	  let parent = node.node.parent;
27	  while (parent) {
28	    if (SKIP_PARENT_TYPES.has(parent.name)) {
29	      return true;
30	    }
31	    parent = parent.parent as { name: string; parent: unknown } | null;
32	  }
33	  return false;
34	}
