36	/**
37	 * Live Preview Plugin
38	 *
39	 * Handles animated show/hide of inline marks (bold, italic, strikethrough, etc.)
40	 * and block marks (headings, lists, quotes)
41	 *
42	 * How it works:
43	 * 1. Traverse syntax tree to find all mark nodes
44	 * 2. Decide whether to show marks based on cursor position
45	 * 3. Apply CSS classes to trigger animations
46	 */
47	export const livePreviewPlugin = ViewPlugin.fromClass(
48	  class {
49	    decorations: DecorationSet;
50	
51	    constructor(view: EditorView) {
52	      this.decorations = this.build(view);
53	    }
54	
55	    update(update: ViewUpdate) {
56	      if (checkUpdateAction(update) === 'rebuild') {
57	        this.decorations = this.build(update.view);
58	      }
59	    }
60	
61	    build(view: EditorView) {
62	      const decorations: Range<Decoration>[] = [];
63	      const { state } = view;
64	
65	      // Get all active lines
66	      const activeLines = new Set<number>();
67	      for (const range of state.selection.ranges) {
68	        const startLine = state.doc.lineAt(range.from).number;
69	        const endLine = state.doc.lineAt(range.to).number;
70	        for (let l = startLine; l <= endLine; l++) {
71	          activeLines.add(l);
72	        }
73	      }
74	
75	      const isDrag = state.field(mouseSelectingField, false);
76	
77	      // Traverse syntax tree
78	      syntaxTree(state).iterate({
79	        enter: (node) => {
80	          // Only handle mark nodes
81	          const markTypes = [
82	            'EmphasisMark', // * or _
83	            'StrikethroughMark', // ~~
84	            'CodeMark', // `
85	            'HeaderMark', // #
86	            'ListMark', // - or *
87	            'QuoteMark', // >
88	          ];
89	
90	          if (!markTypes.includes(node.name)) return;
91	
92	          // Skip marks inside code blocks
93	          if (isInsideSkippedParent(node)) {
94	            return;
95	          }
96	
97	          // Skip CodeMark for math formulas (handled by mathPlugin)
98	          if (node.name === 'CodeMark') {
99	            const parent = node.node.parent;
100	            if (parent && parent.name === 'InlineCode') {
101	              const text = state.doc.sliceString(parent.from, parent.to);
102	              // If it's math formula format `$...$`, skip
103	              if (text.startsWith('`$') && text.endsWith('$`')) {
104	                return;
105	              }
106	            }
107	          }
108	
109	          const isBlock = ['HeaderMark', 'ListMark', 'QuoteMark'].includes(
110	            node.name
111	          );
112	          const lineNum = state.doc.lineAt(node.from).number;
113	          const isActiveLine = activeLines.has(lineNum);
114	
115	          if (isBlock) {
116	            // Block marks: use fontSize animation
117	            const cls =
118	              isActiveLine && !isDrag
119	                ? 'cm-formatting-block cm-formatting-block-visible'
120	                : 'cm-formatting-block';
121	            decorations.push(
122	              Decoration.mark({ class: cls }).range(node.from, node.to)
123	            );
124	          } else {
125	            // Inline marks: use max-width animation
126	            if (node.from >= node.to) return;
127	
128	            const isTouched = shouldShowSource(state, node.from, node.to);
129	            const cls =
130	              isTouched && !isDrag
131	                ? 'cm-formatting-inline cm-formatting-inline-visible'
132	                : 'cm-formatting-inline';
133	
134	            decorations.push(
135	              Decoration.mark({ class: cls }).range(node.from, node.to)
136	            );
137	          }
138	        },
139	      });
140	
141	      return Decoration.set(
142	        decorations.sort((a, b) => a.from - b.from),
143	        true
144	      );
145	    }
146	  },
147	  {
148	    decorations: (v) => v.decorations,
149	  }
150	);
