32	/**
33	 * Markdown Style Plugin
34	 *
35	 * Applies styles to Markdown elements (heading sizes, bold, italic, etc.)
36	 *
37	 * Note: This plugin only handles style application, not mark show/hide
38	 */
39	export const markdownStylePlugin = ViewPlugin.fromClass(
40	  class {
41	    decorations: DecorationSet;
42	
43	    constructor(view: EditorView) {
44	      this.decorations = this.build(view);
45	    }
46	
47	    update(update: ViewUpdate) {
48	      if (update.docChanged || update.viewportChanged) {
49	        this.decorations = this.build(update.view);
50	      }
51	    }
52	
53	    build(view: EditorView) {
54	      const decorations: Range<Decoration>[] = [];
55	
56	      // Style mapping table
57	      const styleMap: Record<string, string> = {
58	        ATXHeading1: 'cm-header-1',
59	        ATXHeading2: 'cm-header-2',
60	        ATXHeading3: 'cm-header-3',
61	        ATXHeading4: 'cm-header-4',
62	        ATXHeading5: 'cm-header-5',
63	        ATXHeading6: 'cm-header-6',
64	        StrongEmphasis: 'cm-strong',
65	        Emphasis: 'cm-emphasis',
66	        Strikethrough: 'cm-strikethrough',
67	        InlineCode: 'cm-code',
68	        Link: 'cm-link',
69	      };
70	
71	      syntaxTree(view.state).iterate({
72	        enter: (node) => {
73	          const cls = styleMap[node.name];
74	          if (!cls) return;
75	
76	          // Skip nodes inside code blocks
77	          if (isInsideSkippedParent(node)) {
78	            return;
79	          }
80	
81	          decorations.push(
82	            Decoration.mark({ class: cls }).range(node.from, node.to)
83	          );
84	
85	          // Headings also need line-level decoration
86	          if (node.name.startsWith('ATXHeading')) {
87	            decorations.push(
88	              Decoration.line({ class: 'cm-heading-line' }).range(node.from)
89	            );
90	          }
91	        },
92	      });
93	
94	      return Decoration.set(decorations, true);
95	    }
96	  },
97	  {
98	    decorations: (v) => v.decorations,
99	  }
100	);
