1	/**
2	 * Inline Markdown → HTML conversion for table cells
3	 */
4	
5	function escapeHtml(text: string): string {
6	  return text
7	    .replace(/&/g, '&amp;')
8	    .replace(/</g, '&lt;')
9	    .replace(/>/g, '&gt;')
10	    .replace(/"/g, '&quot;');
11	}
12	
13	/**
14	 * Convert inline markdown to HTML.
15	 *
16	 * Processing order: escape HTML first, then replace patterns by priority
17	 * (inline code > bold > italic > strikethrough > highlight) to avoid
18	 * nested conflicts.
19	 */
20	export function renderInlineMarkdown(text: string): string {
21	  let result = escapeHtml(text);
22	
23	  // Inline code (highest priority — protect from further replacements)
24	  const codeBlocks: string[] = [];
25	  result = result.replace(/`([^`]+)`/g, (_match, code) => {
26	    const idx = codeBlocks.length;
27	    codeBlocks.push(`<code class="cm-code">${code}</code>`);
28	    return `%%CODE${idx}%%`;
29	  });
30	
31	  // Bold: **text** or __text__
32	  result = result.replace(/\*\*(.+?)\*\*/g, '<strong class="cm-strong">$1</strong>');
33	  result = result.replace(/__(.+?)__/g, '<strong class="cm-strong">$1</strong>');
34	
35	  // Italic: *text* or _text_
36	  result = result.replace(/\*(.+?)\*/g, '<em class="cm-emphasis">$1</em>');
37	  result = result.replace(/_(.+?)_/g, '<em class="cm-emphasis">$1</em>');
38	
39	  // Strikethrough: ~~text~~
40	  result = result.replace(/~~(.+?)~~/g, '<del class="cm-strikethrough">$1</del>');
41	
42	  // Highlight: ==text==
43	  result = result.replace(/==(.+?)==/g, '<mark class="cm-highlight">$1</mark>');
44	
45	  // Restore code blocks
46	  result = result.replace(/%%CODE(\d+)%%/g, (_match, idx) => codeBlocks[Number(idx)]);
47	
48	  return result;
49	}
